CREATE TABLE `real_estate` (
  `house_id` BIGINT PRIMARY KEY,
  `title` TEXT,
  `price` TEXT,
  `address` TEXT,
  `floor` FLOAT,
  `deposit_type` TEXT,
  `management_fee` BIGINT,
  `available_from` TEXT,
  `house_num` BIGINT,
  `agent_comm` BIGINT,
  `agent_info` TEXT,
  `rooms_count` FLOAT,
  `options` TEXT,
  `posted_at` TEXT,
  `gu` TEXT,
  `dong` TEXT,
  `img_url` TEXT,
  `area_size` TEXT,
  `direction` TEXT,
  `built_date` TEXT,
  `parking` BIGINT,
  `building_type` TEXT,
  `house_feature` TEXT,
  `house_explanations` TEXT,
  `apt_name` TEXT,
  `safety_grade` TEXT,
  `deposit` BIGINT,
  `monthly_rent` BIGINT,
  `space` BIGINT,
  `bath_count` FLOAT,
  `total_floor` BIGINT,
  `gpt_description` TEXT
);

INSERT IGNORE INTO real_estate VALUES (1302, '상가주택3층', '전세2억(1,002만원/3.3㎡)', '서울시 성동구 옥수동 296-15', 3.0, '전세', 5000, '즉시입주 협의가능', 2523247128, 600000, '이레공인중개사사무소', 1.0, '옵션 정보 없음', '2025-05-02', '성동구', '옥수동', '["https://landthumb-phinf.pstatic.net/20250502_11/1746146754484gSWHB_JPEG/1741139064980722.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250502_276/1746146754485PgDVV_JPEG/1741139065114197.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250502_278/174614675448446eQK_JPEG/1741139065234107.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250502_219/1746146754484dWR7I_JPEG/1741139065392503.jpg?type=m400_350"]', '66㎡/34㎡(전용률52%)', '남향(거실 기준)', '1994-06-21', 0, '단독주택', '올수리된 분리형 원룸으로 옥수역 도보1분 올수리된 예쁜집', '매물 설명 없음', '상가주택', '짱안전', 200000000, 0, 10, 1.0, 3, '이 매물은 올수리된 분리형 원룸으로, 옥수역에서 도보로 단 1분 거리에 위치해 있어 뛰어난 교통 접근성을 자랑합니다. 새롭게 수리된 공간은 깔끔하고 현대적인 분위기를 자아내며, 효율적인 구조로 설계되어 생활의 편리함을 더합니다. 주변에는 다양한 편의시설이 잘 갖추어져 있어 일상생활에 필요한 모든 것을 손쉽게 해결할 수 있습니다. 이 매물은 교통과 생활 편의성을 동시에 갖춘 실용적인 선택지입니다.');
INSERT IGNORE INTO real_estate VALUES (7344, '다가구고층', '월세1억 5,000/60', '서울시 용산구 원효로2가 16-4', NULL, '월세', 3000, '2025년 6월 20일 협의가능', 2523865252, 630000, '용산프라임공인중개사', 2.0, '가스레인지, 세탁기, 신발장, 싱크대, 벽걸이에어컨, 현관보안, 베란다', '2025-05-07', '용산구', '원효로2가', '["https://landthumb-phinf.pstatic.net/20250507_39/1746577241321nTTXk_JPEG/bc9175bd-e82e-4429-8916-3f3f1a54ff40.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250507_261/17465772413201SRwq_JPEG/c614b603-4fc3-4421-8fb1-598b0b03eeb2.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250507_124/1746577241321YFjSe_JPEG/33e48868-60ec-4ae2-84ac-2298686b63d1.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250507_242/17465772413232FoNv_JPEG/ce5cb660-6af5-4779-8bac-86a87034508a.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250507_289/1746577241324hgHmy_JPEG/acdb17dd-10ff-486a-b537-d98a0a5d787e.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250507_107/17465772413195UhOL_JPEG/c0789c29-d4f7-4fa3-9376-5e5ce5174b04.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250507_214/1746577241320ojTuA_JPEG/f6e2f87e-88a1-4b05-82e6-54bb26e99214.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250507_243/1746577241322TSFC7_JPEG/f0ca924c-cd9e-4cbd-bf8d-32a7e5c476c5.jpg?type=m400_350"]', '53.8㎡/49.88㎡(전용률93%)', '남향(거실 기준)', NULL, 0, '단독주택', '애완견 전용큰2룸 거실 올수리 일반전세대출 전철역8분 내부밝고상태최고', '15평 도배 장판교체 고층뷰 채광 조망굿 버팀목대출안됨 공영주차장이용', '다가구고층', '짱안전', 150000000, 600000, 15, 1.0, 5, '이 매물은 애완견을 위한 배려가 돋보이는 전용 큰 2룸 구조로, 깔끔하게 올수리된 상태입니다. 가스레인지와 세탁기, 벽걸이 에어컨 등의 생활 필수 옵션이 잘 갖춰져 있으며, 넓은 베란다는 애완견과 함께 여유로운 시간을 보내기에 적합합니다. 특히 15평의 넉넉한 공간은 최근 도배와 장판을 교체하여 더욱 쾌적한 생활 환경을 제공합니다. 내부는 밝고 환하게 자연광이 들어와 채광이 뛰어나며, 고층에 위치하여 멋진 조망을 자랑합니다. 또한, 현관 보안이 잘 되어 있어 안전한 생활이 가능합니다. 교통 면에서도 전철역까지 도보 8분 거리로 접근성이 좋으며, 차량 소유자를 위한 공영주차장 이용이 가능합니다.');
