INSERT IGNORE INTO real_estate VALUES (7763, '삼창(삼창플라자) 1동12층', '월세500/50', '주소 정보 없음', 12.0, '월세', 23000, '즉시입주', 2524856052, 220000, 'OK공인중개사사무소', 1.0, '천장에어컨', '2025-05-09', '마포구', '도화동', '["https://landthumb-phinf.pstatic.net/20250509_20/1746779949521dvJVb_JPEG/prh_%BB%EF%C3%A2_1234%C8%A3_1.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250509_15/1746779949521A8bdx_JPEG/prh_%BB%EF%C3%A2_1234%C8%A3_3.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250509_189/1746779949613clT1A_JPEG/prh_%BB%EF%C3%A2_1234%C8%A3_2.jpg?type=m400_350"]', '40.14㎡/24.24㎡(전용률60%)', '남동향(거실 기준)', NULL, 0, '업무시설', '공덕역 도보로 5분거리 올리모델링 사무실', '**마포대로변 대형 빌딩내 인기 좋은 사무실!
