INSERT IGNORE INTO real_estate VALUES (3571, '빌라2층', '월세3,000/100', '서울시 성북구 성북동 145-51', 2.0, '월세', 7000, '즉시입주', 2524722506, 390000, '예스부동산공인중개사사무소', 2.0, '신발장, 냉장고, 세탁기, 싱크대, 인덕션레인지, 천장에어컨, 카드키, CCTV, 현관보안, 베란다', '2025-05-09', '성북구', '성북동', '["https://landthumb-phinf.pstatic.net/20250509_16/1746763251844W3NCB_JPEG/1744268685_16ZJ2.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250509_273/1746763251846jQ873_JPEG/1744268684_11P73.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250509_107/1746763251844vXpvj_JPEG/1744268685_88164.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250509_76/1746763251845VKlvC_JPEG/1744268684_18T78.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250509_14/1746763251844DF452_JPEG/1744268684_62M3X.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250509_165/1746763251845GAbMK_JPEG/1744268683_20R0O.jpg?type=m400_350", "https://landthumb-phinf.pstatic.net/20250509_36/1746763251845NqGkX_JPEG/1744268684_7802W.jpg?type=m400_350"]', '35.74㎡/29.34㎡(전용률82%)', '북동향(거실 기준)', '2022-10-20', 0, '공동주택', '신축3년,풀옵션투룸 월세', '안녕하세요 예스부동산입니다.

