INSERT IGNORE INTO real_estate VALUES (11866, '한라운종가 1동중층', '월세1,000/95', '주소 정보 없음', NULL, '월세', 15000, '2025년 7월 14일', 2523840707, 420000, '샤인부동산공인중개사사무소', 1.0, '옵션 정보 없음', '2025-05-05', '종로구', '숭인동', '[]', '48.84㎡/23.04㎡(전용률47%)', '남향(거실 기준)', NULL, 0, '건축물 용도 정보 없음', '남향, 청계천조망, 7월 중순 입주, 사업자, 신설동역 역세권', '안녕하세요
